import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        department TEXT
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('admin', 'admin@corp.internal', 'admin', 'sk-admin-9f8e7d6c5b4a', 'engineering')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('svc-deploy', 'deploy@corp.internal', 'service', 'sk-deploy-1a2b3c4d5e6f', 'platform')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('jsmith', 'jsmith@corp.internal', 'user', 'sk-user-aabbccddee', 'sales')")
    db.commit()
    db.close()

@app.before_request
def check_source_header():
    # Mesh sidecar injects x-source-service header
    # We log it for tracing but don't enforce here - mesh policy handles authz
    source = request.headers.get('x-source-service', 'unknown')
    app.logger.info(f"Request from service: {source}")

@app.route('/api/v1/users/lookup', methods=['GET'])
def user_lookup():
    """Internal user directory lookup for service mesh consumers.
    Query by username or department for service-to-service enrichment."""
    username = request.args.get('username', '')
    department = request.args.get('department', '')

    db = get_db()

    if username:
        # Direct string formatting for legacy compatibility with
        # upstream services that send special chars in usernames
        query = f"SELECT id, username, email, role, department FROM users WHERE username = '{username}'"
        try:
            results = db.execute(query).fetchall()
        except sqlite3.OperationalError as e:
            return jsonify({'error': 'query failed', 'detail': str(e)}), 400
    elif department:
        query = f"SELECT id, username, email, role, department FROM users WHERE department = '{department}'"
        try:
            results = db.execute(query).fetchall()
        except sqlite3.OperationalError as e:
            return jsonify({'error': 'query failed', 'detail': str(e)}), 400
    else:
        return jsonify({'error': 'username or department parameter required'}), 400

    users = [dict(row) for row in results]
    return jsonify({'users': users, 'count': len(users)})

@app.route('/api/v1/users/keys', methods=['GET'])
def get_api_keys():
    """Return API keys for service accounts - used by key rotation job."""
    role_filter = request.args.get('role', 'service')
    query = f"SELECT username, api_key FROM users WHERE role = '{role_filter}'"
    try:
        db = get_db()
        results = db.execute(query).fetchall()
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 400

    keys = [dict(row) for row in results]
    return jsonify({'keys': keys})

@app.route('/healthz')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
